import * as THREE from './vendor/three.module.js';
import {organelles,secretion} from './cell-data.js';
const $=id=>document.getElementById(id),byId=Object.fromEntries(organelles.map(o=>[o.id,o]));
let renderer,scene,camera,root,selected='nucleus',tour=-1,tourStart=0,tourPlaying=false,lastFrame=0,ready=false;
let azimuth=.65,elevation=.73,distance=12.6;const groups={},markers={},meshes=[],labelNodes={},ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let cargo;
const vec=p=>new THREE.Vector3(...p);
function group(id,pos=[0,0,0]){const g=new THREE.Group();g.userData.organelle=id;g.position.set(...pos);root.add(g);groups[id]=g;return g}
function material(color,opacity=1){const m=new THREE.MeshStandardMaterial({color,roughness:.52,metalness:.03,transparent:opacity<1,opacity,side:THREE.DoubleSide,depthWrite:opacity>=1});m.userData.baseOpacity=opacity;return m}
function add(g,geometry,color,pos=[0,0,0],scale=[1,1,1],opacity=1){const m=new THREE.Mesh(geometry,material(color,opacity));m.position.set(...pos);m.scale.set(...scale);m.userData.organelle=g.userData.organelle;g.add(m);meshes.push(m);return m}
function sphere(g,pos,scale,color,opacity=1){return add(g,new THREE.SphereGeometry(1,28,18),color,pos,scale,opacity)}
function tube(g,points,r,color){return add(g,new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points.map(vec)),40,r,7,false),color)}
function mark(id,p){markers[id]=vec(p);const b=document.createElement('span');b.className='cell-label';b.textContent=byId[id].name;labelNodes[id]=b;$('cellLabels').append(b)}
function build(){root=new THREE.Group();scene.add(root);
 const mem=group('membrane');add(mem,new THREE.SphereGeometry(4.6,56,32,0,Math.PI*2,Math.PI*.38,Math.PI*.62),'#79bea8',[0,0,0],[1,.63,.84],.24);const rim=[];for(let i=0;i<=90;i++){let a=i/90*Math.PI*2;rim.push([4.6*Math.sin(Math.PI*.38)*Math.cos(a),4.6*.63*Math.cos(Math.PI*.38),4.6*.84*Math.sin(Math.PI*.38)*Math.sin(a)])}tube(mem,rim,.035,'#91debd');mark('membrane',[3.4,.75,2]);
 const cyt=group('cytosol');add(cyt,new THREE.SphereGeometry(4.5,36,24,0,Math.PI*2,Math.PI*.5,Math.PI*.5),'#3d776c',[0,0,0],[1,.62,.83],.1);mark('cytosol',[0,-1.8,2.4]);
 const nucleus=group('nucleus',[-.85,.25,-.35]);sphere(nucleus,[0,0,0],[1.25,1.1,1.15],'#a28bd5',.35);for(let k=0;k<4;k++){let pts=[];for(let i=0;i<16;i++){const t=i*.6+k;pts.push([Math.sin(t*1.3)*.75,Math.cos(t*.7+k)*.6,Math.sin(t*.8)*.8])}tube(nucleus,pts,.035,'#c9a9e8')}for(let i=0;i<12;i++){let a=i*Math.PI/6;sphere(nucleus,[Math.cos(a)*1.22,0,Math.sin(a)*1.12],[.065,.065,.065],'#dfc1ef')}mark('nucleus',[-.85,1.5,-.35]);
 const nucleolus=group('nucleolus',[-.6,.55,.18]);sphere(nucleolus,[0,0,0],[.35,.35,.35],'#d979b7');mark('nucleolus',[-.6,.9,.18]);
 const rer=group('rer');const ribs=group('ribosome');for(let k=0;k<5;k++){const pts=[];for(let i=0;i<28;i++){const a=.55+Math.PI*1.35*i/27;pts.push([-.85-Math.sin(a)*(1.5+k*.1),-.45+k*.21,-.35+Math.cos(a)*(1.55+k*.04)])}const m=tube(rer,pts,.17,'#719bdc');m.scale.y=.85;for(let i=2;i<26;i+=4)sphere(ribs,[pts[i][0],pts[i][1]*.85+.15,pts[i][2]],[.065,.05,.065],'#f2d68c')}
 for(let i=0;i<18;i++){let a=i*2.39,r=2.2+(i%4)*.3;sphere(ribs,[Math.cos(a)*r,-.5+(i%5)*.14,Math.sin(a)*r*.78],[.065,.06,.06],'#f2d68c')}mark('rer',[-2.4,.75,.4]);mark('ribosome',[-2.5,-.15,2]);
 const ser=group('ser');for(let k=0;k<5;k++){const pts=[];for(let i=0;i<16;i++){let t=i/15;pts.push([-2.5+t*1.8,-.65+k*.12,-1.4-k*.15+Math.sin(t*Math.PI*3)*.19])}tube(ser,pts,.085,'#6dc5bb')}mark('ser',[-2.5,-.1,-1.9]);
 const golgi=group('golgi',[1.65,0,-.8]);for(let k=0;k<5;k++){let pts=[];for(let i=0;i<25;i++){let a=-1.2+i/24*2.4;pts.push([Math.sin(a)*(1-k*.06),k*.2-.4,Math.cos(a)*.48])}const m=tube(golgi,pts,.16,'#edb375');m.scale.z=1.4}mark('golgi',[1.7,1,-.55]);
 const mito=group('mitochondrion');const locations=[[1.7,-.55,1.9],[2.8,-.2,-1.7],[-2.5,-.9,-.6]];locations.forEach((p,k)=>{const shell=sphere(mito,p,[.95,.38,.47],'#e8937d',.52);shell.rotation.y=k*.6;let pts=[];for(let i=0;i<24;i++){let t=i/23;pts.push([p[0]-.78+t*1.56,p[1]+Math.sin(t*Math.PI*9)*.21,p[2]+Math.cos(t*Math.PI*9)*.23])}tube(mito,pts,.055,'#ffc299')});mark('mitochondrion',[1.7,0,2]);
 const lys=group('lysosome');sphere(lys,[2.7,-.65,.25],[.38,.38,.38],'#b7cb69',.82);sphere(lys,[3,-.55,.32],[.08,.08,.08],'#e2ed9a');mark('lysosome',[2.7,-.1,.25]);
 const per=group('peroxisome');sphere(per,[-.2,-.9,2.15],[.28,.3,.28],'#74c7d4',.85);mark('peroxisome',[-.2,-.4,2.15]);
 const ves=group('vesicle');[[.35,.1,-1.65],[2.65,.15,-.4],[3.45,.05,.8],[.65,-.6,1]].forEach(p=>sphere(ves,p,[.17,.17,.17],'#e9d282',.88));mark('vesicle',[3.4,.45,.8]);
 const cyto=group('cytoskeleton');for(let k=0;k<5;k++){let a=k*1.3;const p=[Math.cos(a)*3.9,-1.3,Math.sin(a)*3.2];tube(cyto,[[0,-1.6,-1],[(p[0])*.5,-1.5,p[2]*.4],p],.025,'#779fb2')}mark('cytoskeleton',[-2,-1.2,1.7]);
 cargo=new THREE.Mesh(new THREE.SphereGeometry(.17,16,12),new THREE.MeshStandardMaterial({color:'#fff7b3',emissive:'#caae45',emissiveIntensity:1}));root.add(cargo);cargo.visible=false;
}
function cameraPosition(){camera.position.set(distance*Math.cos(elevation)*Math.sin(azimuth),distance*Math.sin(elevation),distance*Math.cos(elevation)*Math.cos(azimuth));camera.lookAt(0,0,0)}
function updateEmphasis(){const isolated=$('cellIsolate').checked;for(const m of meshes){const active=m.userData.organelle===selected,base=m.material.userData.baseOpacity;m.material.opacity=isolated&&!active?Math.min(base,.1):base;m.material.transparent=m.material.opacity<1;m.material.depthWrite=m.material.opacity>=1;m.material.emissive.set(active?'#253a32':'#000000');m.material.emissiveIntensity=active?.55:0}}
function select(id,manual=true){if(manual)pauseTour();selected=id;const o=byId[id];$('orgTag').textContent=o.tag;$('orgName').textContent=o.name;$('orgEnglish').textContent=o.en;$('orgShape').textContent=o.shape;$('orgJob').textContent=o.job;$('orgLink').textContent=o.link;$('orgNote').textContent=o.note;$('nucleusDNA').hidden=id!=='nucleus';$('mitoEnter').hidden=id!=='mitochondrion';$('membraneEnter').hidden=id!=='membrane';$('cellSelectionStatus').textContent='已选择：'+o.name;document.querySelectorAll('[data-org]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.org===id));if(ready)updateEmphasis()}
function directory(){const tags=[...new Set(organelles.map(o=>o.tag))];for(const tag of tags){const section=document.createElement('div');section.className='org-group';const h=document.createElement('h3');h.textContent=tag;const list=document.createElement('div');organelles.filter(o=>o.tag===tag).forEach(o=>{let b=document.createElement('button');b.dataset.org=o.id;b.textContent=o.name;b.style.setProperty('--org',o.color);b.onclick=()=>select(o.id);list.append(b)});section.append(h,list);$('organelleDirectory').append(section)}}
function pauseTour(){tourPlaying=false;$('cellTourPlay').textContent=tour===4?'重播旅程':'播放旅程'}
function tourStep(i){tour=Math.max(0,Math.min(4,i));tourStart=performance.now();const step=secretion[tour];select(step.id,false);$('cellTourTitle').textContent=(tour+1)+' / 5 · '+step.title;$('cellTourText').textContent=step.text;$('orgLink').textContent=step.text;$('cellSelectionStatus').textContent=(tour+1)+' / 5 · '+step.cargo+' · '+byId[step.id].name;$('cellTourPrev').disabled=tour===0;$('cellTourNext').textContent=tour===4?'回到起点':'下一步';document.querySelectorAll('[data-tour]').forEach((b,j)=>b.setAttribute('aria-pressed',j===tour));if(ready){cargo.visible=true;cargo.position.copy(vec(step.from));cargo.material.color.set(tour===0?'#b9d9ff':'#fff1a6')}}
function tourControls(){['细胞核','粗面内质网','运输囊泡','高尔基体','细胞膜'].forEach((s,i)=>{const b=document.createElement('button');b.textContent='0'+(i+1)+' '+s;b.dataset.tour=i;b.onclick=()=>{pauseTour();tourStep(i)};$('cellTourSteps').append(b)});$('cellTourPlay').onclick=()=>{if(tourPlaying){pauseTour();return}tourStep(tour<0||tour===4?0:tour);tourStart=performance.now();tourPlaying=true;$('cellTourPlay').textContent='暂停旅程';document.querySelector('.cell-workspace').scrollIntoView({behavior:'smooth',block:'start'})};$('cellTourPrev').onclick=()=>{pauseTour();tourStep(tour-1)};$('cellTourNext').onclick=()=>{pauseTour();tourStep((tour+1)%5)};$('cellTourExit').onclick=()=>{pauseTour();tour=-1;if(cargo)cargo.visible=false;document.querySelectorAll('[data-tour]').forEach(b=>b.setAttribute('aria-pressed','false'));$('cellTourTitle').textContent='自由探索';$('cellTourText').textContent='选择模型或图鉴中的结构查看详解。点击播放旅程可重新开始。'};tourStep(0);}
function quiz(){const choices=['分泌蛋白可能无法被正确分类并送达目的地','所有 DNA 的碱基序列立即改变','核糖体再也不能读取任何 mRNA'];$('cellQuizChoices').replaceChildren();$('cellQuizFeedback').textContent='';$('cellQuizRetry').hidden=true;choices.forEach((s,i)=>{let b=document.createElement('button');b.textContent=String.fromCharCode(65+i)+' · '+s;b.onclick=()=>{[...$('cellQuizChoices').children].forEach((x,j)=>{x.disabled=true;x.classList.toggle('correct',j===0);x.classList.toggle('wrong',j===i&&i!==0)});$('cellQuizFeedback').textContent=(i===0?'正确。':'再想一想。')+'高尔基体参与加工与分选；功能受损可影响分泌货物的去向，并不等于所有转录或翻译立即停止。';$('cellQuizRetry').hidden=false};$('cellQuizChoices').append(b)});$('cellQuizRetry').onclick=quiz}
function labels(){const rect=$('cellViewport').getBoundingClientRect(),occupied=[];const order=[selected,'nucleus','rer','golgi','mitochondrion'];Object.values(labelNodes).forEach(n=>n.hidden=true);if(!$('cellShowLabels').checked)return;for(const id of new Set(order)){const p=markers[id].clone().project(camera),x=(p.x*.5+.5)*rect.width,y=(-p.y*.5+.5)*rect.height;if(p.z>1||x<45||x>rect.width-45||y<45||y>rect.height-20)continue;if(occupied.some(q=>Math.abs(q[0]-x)<95&&Math.abs(q[1]-y)<32))continue;const label=labelNodes[id];label.hidden=false;label.style.left=x+'px';label.style.top=y+'px';label.classList.toggle('selected',id===selected);occupied.push([x,y])}}
function controls(){const canvas=$('cellCanvas');let down=null,moved=false;canvas.onpointerdown=e=>{down=[e.clientX,e.clientY];moved=false;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!down)return;const dx=e.clientX-down[0],dy=e.clientY-down[1];if(Math.abs(dx)+Math.abs(dy)>2)moved=true;azimuth-=dx*.006;elevation=Math.max(.15,Math.min(1.45,elevation+dy*.005));down=[e.clientX,e.clientY];cameraPosition()};canvas.onpointerup=e=>{down=null;if(moved)return;const r=canvas.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hits=ray.intersectObjects(meshes).filter(h=>!['membrane','cytosol','cytoskeleton'].includes(h.object.userData.organelle));if(hits[0])select(hits[0].object.userData.organelle)};canvas.onpointercancel=()=>down=null;canvas.addEventListener('wheel',e=>{e.preventDefault();distance=Math.max(7,Math.min(19,distance+e.deltaY*.008));cameraPosition()},{passive:false});canvas.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')azimuth-=.1;if(e.key==='ArrowRight')azimuth+=.1;if(e.key==='ArrowUp')elevation=Math.min(1.45,elevation+.1);if(e.key==='ArrowDown')elevation=Math.max(.15,elevation-.1);if(e.key==='+'||e.key==='=')distance=Math.max(7,distance-.7);if(e.key==='-')distance=Math.min(19,distance+.7);cameraPosition()};$('cellReset').onclick=()=>{azimuth=.65;elevation=.73;distance=12.6;cameraPosition()};$('cellIsolate').onchange=updateEmphasis;}
function animate(t){requestAnimationFrame(animate);if(!ready||document.hidden||$('cellMain').hidden){lastFrame=t;return}if(tour>=0&&cargo.visible&&tourPlaying){let u=Math.min(1,(t-tourStart)/4200),ease=u*u*(3-2*u);cargo.position.lerpVectors(vec(secretion[tour].from),vec(secretion[tour].to),ease);if(u>=1){if(tour<4){const nextStart=tourStart+4200;tourStep(tour+1);tourStart=nextStart}else pauseTour()}}if(t-lastFrame>=33){renderer.render(scene,camera);labels();lastFrame=t}}
export function initCell(){directory();tourControls();quiz();$('nucleusDNA').onclick=()=>{pauseTour();window.showBioWorld('dna')};$('mitoEnter').onclick=()=>{pauseTour();window.showBioWorld('mito')};select('nucleus',false);try{renderer=new THREE.WebGLRenderer({canvas:$('cellCanvas'),antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setClearColor('#102333');renderer.outputColorSpace=THREE.SRGBColorSpace;scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(42,1,.1,100);scene.add(new THREE.HemisphereLight('#e0f5ff','#34594f',2.4));const light=new THREE.DirectionalLight('#fff4dd',3);light.position.set(4,8,6);scene.add(light);const fill=new THREE.DirectionalLight('#a9c9ff',1);fill.position.set(-5,2,-5);scene.add(fill);build();cameraPosition();ready=true;updateEmphasis();controls();new ResizeObserver(()=>{const r=$('cellViewport').getBoundingClientRect();if(r.width<1||r.height<1)return;renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()}).observe($('cellViewport'));$('cellLoading').hidden=true;$('cellCanvas').dataset.ready='true';requestAnimationFrame(animate)}catch(e){$('cellLoading').textContent='此设备暂时无法显示三维模型。仍可使用下方图鉴、旅程和详解学习。';console.error('Cell renderer failed',e)}document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseTour()});window.addEventListener('bioworldchange',()=>pauseTour());}
